@startuml

class EBike {
  + modelName : string
  + serialNumber : string
}

class Frame {
  + material : string
}

class DriveSystem {
  + driveType : string
}

class Motor {
  + powerOutput : double
}

class Controller {
  + state : ControllerState
}

class BasicController {}

class AdvancedController {
  + nextInspectionDate : date
}

class Battery {
  + energyCapacityWh : double
  + isRemovable : boolean
}

class Wheel {
  + size : string
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
EBike "0..1" o-- "1" Battery
Frame "1" *-- "2" Wheel
DriveSystem "1" *-- "1" Motor
Controller "1" --> "0..1" Battery : controls
Controller "1" --> "1" DriveSystem : commands
BasicController --|> Controller
AdvancedController --|> Controller

@enduml

